import React from 'react';
import TopBar from './components/TopBar';
import InfoBar from './components/InfoBar';
import SortButtons from './components/SortButtons';
import VersionList from './components/VersionList';
import ChartSection from './components/ChartSection';
import ChatSection from './components/ChatSection';
import { useApi } from './hooks/useApi';
import './styles/styles.css';

const App = () => {
  const { data: versions, loading } = useApi('https://releasetrain.io/api/v');

  const dummyLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  const dummyData = [4, 6, 3, 8, 2];

  return (
    <div className="app-container">
      <TopBar />
      <InfoBar />
      <SortButtons onSort={(type) => console.log('Sort:', type)} />
      {loading ? <p>Loading versions...</p> : <VersionList data={versions.versions || []} />}
      <ChartSection title="Updates in Last 5 Days" labels={dummyLabels} data={dummyData} />
      <ChatSection />
    </div>
  );
};

export default App;
